var WATCH_SOURCE_TYPES = ["newsletter", "podcast", "youtube", "tiktok", "linkedin", "blog", "revue", "site", "autre"];
function normalizeWatchSourceUrl(value) {
  const raw = value.trim().toLowerCase();
  const parsed = new URL(raw);
  if (!["http:", "https:"].includes(parsed.protocol) || /\s/.test(raw) || !parsed.hostname) {
    throw new Error("URL HTTP(S) invalide");
  }
  const withoutFragment = raw.split("#")[0];
  const question = withoutFragment.indexOf("?");
  const base = (question < 0 ? withoutFragment : withoutFragment.slice(0, question)).replace(/\/+$/, "");
  const params = question < 0 ? [] : withoutFragment.slice(question + 1).split("&").filter((p) => p && !p.split("=")[0].startsWith("utm_"));
  return base + (params.length ? `?${params.join("&")}` : "");
}

